 auto mainKeys=[&](){return std::vector<std::vector<std::pair<std::string,std::string>>>{{{"👥 Аккаунты","menu_accounts"},{"💬 Все диалоги","menu_chats"}},{{"📊 Статус","menu_status"},{"ℹ️ Помощь","menu_help"}}};};
