 bot.setPeriodicHandler([&](){for(auto&a:db.getCustoJustoAccounts()){if(!a.enabled||!a.loggedIn)continue;auto*c=client(a.id);c->setBaseUrl(a.loginUrl);auto ds=c->getConversations();if(!c->isLoggedIn()){db.setCustoJustoAccountLoggedIn(a.id,false);continue;}for(auto&d:ds){long long cid=db.upsertCustoJustoConversation(a.id,d.url,d.listingUrl,d.listingTitle.empty()?d.title:d.listingTitle,d.buyerName,d.lastMessageId,d.lastMessage,0,d.unread);bool baseline=db.getCustoJustoMessages(cid,1).empty();for(auto&x:c->getMessages(d.url)){if(db.hasCustoJustoExternalMessage(a.id,x.id))continue;std::string tr=x.text;if(x.incoming)try{if(ai.enabled()){MessageRecord q;q.incoming=true;q.text="Переведи на русский, только перевод:\n"+x.text;tr=ai.generateReply({q},"Ты точный переводчик с европейского португальского на русский. Верни только перевод.");}}catch(...){ }db.saveCustoJustoMessage(a.id,cid,x.id,x.sender,x.text,tr,x.incoming);if(!x.incoming||baseline)continue;if(!ai.enabled()){bot.sendMessage(owner,"📩 Новое сообщение\n\n"+tr);continue;}try{std::vector<MessageRecord>h;for(auto&r:db.getCustoJustoMessages(cid,cfg.aiHistoryLimit)){MessageRecord z;z.incoming=r.incoming;z.text=r.originalText;h.push_back(z);}makeDraft(a.id,cid,d.url,h,x.text,tr);}catch(const std::exception&e){bot.sendMessage(owner,std::string("🔴 Ошибка AI: ")+e.what());}}}}},45);
